import React, { useRef, useEffect } from 'react';

// Pure gradient orb — no edges, just colour dissolving into the background
// Like the aura/gradient art references. Shifts colour based on mood via distort param.
export default function MeshSphere({ size = 300, speed = 0.4, distort = 0.5 }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width  = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const cx = size / 2, cy = size / 2;

    // Colour palette — shifts slowly like breathing
    // distort 0 = calm blue, 1 = warm orange/pink, 0.5 = default purple/lavender
    const getHues = () => {
      const base = t.current * 0.04 * speed;
      const mood = distort; // 0 = calm, 1 = stressed/warm

      // Blend between cool (calm) and warm (stressed)
      const inner  = 200 + (1 - mood) * 40 + Math.sin(base * 0.7) * 12;  // blue → purple
      const mid    = 260 + (mood * 60)       + Math.cos(base * 0.5) * 14; // purple → pink
      const outer  = 300 + (mood * 40)       + Math.sin(base * 0.4) * 16; // lavender → rose

      // For high distort (stressed), shift toward orange/red
      const warmShift = mood * 80;
      return {
        c1: inner  - warmShift,
        c2: mid    - warmShift * 0.7,
        c3: outer  - warmShift * 0.5,
        c4: outer  - warmShift * 0.3 + 30,
      };
    };

    const draw = () => {
      t.current += 0.008 * speed;
      ctx.clearRect(0, 0, size, size);

      const hues = getHues();
      const pulse = 1 + Math.sin(t.current * 0.5) * 0.04; // gentle breathe

      // The orb is ONLY radial gradients — multiple concentric ones
      // that overlap and blend, no hard clip, no stroke

      // ── Layer 1: Wide outer glow — dissolves far into bg ───
      const r1 = size * 0.49 * pulse;
      const g1 = ctx.createRadialGradient(cx, cy, 0, cx, cy, r1);
      g1.addColorStop(0,    `hsla(${hues.c1}, 75%, 68%, 0.22)`);
      g1.addColorStop(0.35, `hsla(${hues.c2}, 70%, 65%, 0.16)`);
      g1.addColorStop(0.65, `hsla(${hues.c3}, 65%, 70%, 0.08)`);
      g1.addColorStop(1,    `hsla(${hues.c4}, 60%, 75%, 0)`);
      ctx.fillStyle = g1;
      ctx.fillRect(0, 0, size, size);

      // ── Layer 2: Core body — saturated, rich colour ─────────
      const r2 = size * 0.35 * pulse;
      const offX = Math.sin(t.current * 0.3) * size * 0.025;
      const offY = Math.cos(t.current * 0.25) * size * 0.02;
      const g2 = ctx.createRadialGradient(cx + offX, cy + offY, 0, cx + offX, cy + offY, r2);
      g2.addColorStop(0,    `hsla(${hues.c1 + 15}, 80%, 72%, 0.85)`);
      g2.addColorStop(0.3,  `hsla(${hues.c1},      78%, 65%, 0.75)`);
      g2.addColorStop(0.6,  `hsla(${hues.c2},      72%, 62%, 0.55)`);
      g2.addColorStop(0.85, `hsla(${hues.c3},      65%, 65%, 0.25)`);
      g2.addColorStop(1,    `hsla(${hues.c3},      60%, 70%, 0)`);
      ctx.fillStyle = g2;
      ctx.fillRect(0, 0, size, size);

      // ── Layer 3: Secondary colour blob — moves opposite ─────
      const r3 = size * 0.28 * pulse;
      const ox2 = -Math.sin(t.current * 0.28) * size * 0.04;
      const oy2 = -Math.cos(t.current * 0.22) * size * 0.035;
      const g3 = ctx.createRadialGradient(cx + ox2, cy + oy2, 0, cx + ox2, cy + oy2, r3);
      g3.addColorStop(0,    `hsla(${hues.c2 + 20}, 75%, 68%, 0.70)`);
      g3.addColorStop(0.4,  `hsla(${hues.c2},      70%, 65%, 0.45)`);
      g3.addColorStop(0.75, `hsla(${hues.c3},      65%, 68%, 0.18)`);
      g3.addColorStop(1,    'transparent');
      ctx.fillStyle = g3;
      ctx.fillRect(0, 0, size, size);

      // ── Layer 4: Ring effect — like the blue ring in image 2 ─
      // Creates a bright ring around mid-radius
      const r4inner = size * 0.10 * pulse;
      const r4outer = size * 0.38 * pulse;
      const ox3 = Math.cos(t.current * 0.18) * size * 0.015;
      const oy3 = Math.sin(t.current * 0.22) * size * 0.012;
      const g4 = ctx.createRadialGradient(cx + ox3, cy + oy3, r4inner, cx + ox3, cy + oy3, r4outer);
      g4.addColorStop(0,    `hsla(${hues.c1 + 30}, 70%, 82%, 0.30)`);
      g4.addColorStop(0.25, `hsla(${hues.c1 + 15}, 75%, 70%, 0.55)`);
      g4.addColorStop(0.5,  `hsla(${hues.c1},      78%, 64%, 0.50)`);
      g4.addColorStop(0.75, `hsla(${hues.c2},      72%, 66%, 0.30)`);
      g4.addColorStop(1,    'transparent');
      ctx.fillStyle = g4;
      ctx.fillRect(0, 0, size, size);

      // ── Layer 5: Soft bright centre — light source feel ─────
      const r5 = size * 0.14 * pulse;
      const g5 = ctx.createRadialGradient(cx + offX * 0.5, cy + offY * 0.5, 0, cx, cy, r5);
      g5.addColorStop(0,    `hsla(${hues.c1 + 40}, 80%, 88%, 0.60)`);
      g5.addColorStop(0.5,  `hsla(${hues.c1 + 20}, 75%, 80%, 0.25)`);
      g5.addColorStop(1,    'transparent');
      ctx.fillStyle = g5;
      ctx.fillRect(0, 0, size, size);

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, speed, distort]);

  return (
    <canvas
      ref={canvasRef}
      style={{ display:'block', width:`${size}px`, height:`${size}px` }}
    />
  );
}
